// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading ensures zero flicker
const { fontFamily: interFamily } = loadInter();



export type StructureTakeoverProps = Record<string, any>;

const StructureTakeover: React.FC<StructureTakeoverProps> = ({
  backgroundColor = "#1a1a1c",
  transparentBackground = false,
  durationInSeconds = 5,
  accentColor = "#c5a059",
  phase1Text = "ONE EXPLANATION",
  phase2Title = "THE WHOLE STRUCTURE",
  structureItems = ["Revision", "Approach", "Method", "Understanding"],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background gradient resolution
  const bgGradient = transparentBackground
    ? `${backgroundColor}00`
    : `linear-gradient(180deg, ${backgroundColor} 0%, #080809 100%)`;

  // General cinematic push-in (breathing effect)
  const breathe = interpolate(frame, [0, durationInSeconds * fps], [1, 1.04], {
    extrapolateRight: "extend",
  });

  // --- Phase 1: Isolated Concept ---
  const p1FadeIn = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });
  const p1ScaleIn = spring({ fps, frame, config: { damping: 20 } });
  
  const p1FadeOut = interpolate(frame, [45, 60], [1, 0], { extrapolateRight: "clamp" });
  const p1ScaleOut = spring({ fps, frame: frame - 45, config: { damping: 15 } });

  const phase1Opacity = Math.min(p1FadeIn, p1FadeOut);
  const p1CurrentScaleIn = interpolate(p1ScaleIn, [0, 1], [0.85, 1]);
  const p1CurrentScaleOut = interpolate(p1ScaleOut, [0, 1], [0, 0.15]);
  const phase1Scale = p1CurrentScaleIn - p1CurrentScaleOut;

  // --- Phase 2: System Architecture ---
  const p2Start = 55;
  const p2FadeIn = interpolate(frame, [p2Start, p2Start + 20], [0, 1], { extrapolateRight: "clamp" });
  const p2ScaleIn = spring({ fps, frame: frame - p2Start, config: { damping: 20 } });
  
  const phase2Opacity = p2FadeIn;
  const phase2Scale = interpolate(p2ScaleIn, [0, 1], [0.95, 1]);

  // Phase 2 Title animations
  const titleSlide = spring({ fps, frame: frame - (p2Start + 5), config: { damping: 20 } });
  const titleY = interpolate(titleSlide, [0, 1], [40, 0]);
  const titleFade = interpolate(frame, [p2Start + 5, p2Start + 25], [0, 1], { extrapolateRight: "clamp" });

  // Vertical timeline scale
  const lineScale = spring({ fps, frame: frame - (p2Start + 15), config: { damping: 24 } });

  return (
    <AbsoluteFill style={{ background: bgGradient, fontFamily: interFamily, color: "#ffffff" }}>
      <AbsoluteFill style={{ transform: `scale(${breathe})`, transformOrigin: "center center", transition: "none" }}>
        
        {/* === Gradient Grid Background === */}
        {!transparentBackground && (
          <div style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            opacity: 0.8,
            pointerEvents: "none",
          }}>
            <svg width="100%" height="100%">
              <defs>
                <pattern id="gradientGrid" width="64" height="64" patternUnits="userSpaceOnUse">
                  <path d="M 64 0 L 0 0 0 64" fill="none" stroke={accentColor} strokeWidth="1.5" strokeOpacity="0.15" />
                </pattern>
                <radialGradient id="gridMaskGradient" cx="50%" cy="50%" r="75%">
                  <stop offset="0%" stopColor="white" stopOpacity="1" />
                  <stop offset="100%" stopColor="white" stopOpacity="0" />
                </radialGradient>
                <mask id="gridMask">
                  <rect width="100%" height="100%" fill="url(#gridMaskGradient)" />
                </mask>
              </defs>
              <rect width="100%" height="100%" fill="url(#gradientGrid)" mask="url(#gridMask)" />
            </svg>
          </div>
        )}

        {/* === PHASE 1: Isolated Label === */}
        <div style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: `translate(-50%, -50%) scale(${phase1Scale})`,
          opacity: phase1Opacity,
          padding: "24px 48px",
          background: "linear-gradient(135deg, rgba(255,255,255,0.03), rgba(255,255,255,0.0))",
          border: "1px solid rgba(255,255,255,0.1)",
          borderRadius: "100px",
          boxShadow: "inset 0 0 20px rgba(255,255,255,0.02), 0 10px 30px rgba(0,0,0,0.2)",
          color: "rgba(255,255,255,0.6)",
          fontSize: "32px",
          fontWeight: 500,
          letterSpacing: "0.2em",
          backdropFilter: "blur(20px)",
          WebkitBackdropFilter: "blur(20px)",
          transition: "none",
          pointerEvents: "none"
        }}>
          {phase1Text}
        </div>

        {/* === PHASE 2: Advanced Visual System === */}
        {/* Ambient Glow */}
        <div style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          width: width * 0.8,
          height: height * 0.6,
          transform: `translate(-50%, -50%) scale(${phase2Scale})`,
          opacity: phase2Opacity * 0.25,
          background: `radial-gradient(circle, ${accentColor} 0%, transparent 60%)`,
          transition: "none",
          zIndex: 0
        }} />

        {/* Main Glass Panel */}
        <div style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          width: width * 0.85,
          transform: `translate(-50%, -50%) scale(${phase2Scale})`,
          opacity: phase2Opacity,
          display: "flex",
          flexDirection: "column",
          background: "rgba(255,255,255,0.03)",
          border: "1px solid rgba(255,255,255,0.08)",
          borderRadius: "48px",
          boxShadow: "0 40px 80px rgba(0,0,0,0.6)",
          padding: "64px 48px",
          backdropFilter: "blur(40px)",
          WebkitBackdropFilter: "blur(40px)",
          transition: "none",
          zIndex: 1
        }}>
          
          {/* Title Area (Masked Reveal) */}
          <div style={{ textAlign: "center", marginBottom: "8px" }}>
            <div style={{ overflow: "hidden", paddingBottom: "10px" }}>
               <h2 style={{
                 margin: 0,
                 fontSize: "56px",
                 fontWeight: 700,
                 background: "linear-gradient(180deg, #FFFFFF 0%, rgba(255,255,255,0.6) 100%)",
                 WebkitBackgroundClip: "text",
                 WebkitTextFillColor: "transparent",
                 letterSpacing: "0.08em",
                 transform: `translateY(${titleY}px)`,
                 opacity: titleFade,
                 transition: "none"
               }}>
                 {phase2Title}
               </h2>
            </div>
            {/* Elegant Accent Line */}
            <div style={{
              width: `${interpolate(titleSlide, [0, 1], [0, 80])}px`,
              height: "3px",
              background: accentColor,
              margin: "24px auto 0 auto",
              borderRadius: "2px",
              boxShadow: `0 0 16px ${accentColor}`,
              opacity: titleFade,
              transition: "none"
            }} />
          </div>

          {/* Connective Sections (Timeline) */}
          <div style={{
            position: "relative",
            display: "flex",
            flexDirection: "column",
            gap: "32px",
            marginTop: "32px"
          }}>
            {/* Main Vertical Spine */}
            <div style={{
              position: "absolute",
              left: "22px",
              top: "24px",
              bottom: "24px",
              width: "4px",
              background: `linear-gradient(to bottom, ${accentColor}90, transparent)`,
              transformOrigin: "top",
              transform: `scaleY(${lineScale})`,
              transition: "none",
              borderRadius: "2px",
              zIndex: 1
            }} />

            {/* Iterative Nodes */}
            {structureItems.map((item, idx) => {
              const itemStart = p2Start + 15 + idx * 8;
              const itemPanelFade = interpolate(frame, [itemStart, itemStart + 15], [0, 1], { extrapolateRight: "clamp" });
              const itemFade = interpolate(frame, [itemStart + 5, itemStart + 25], [0, 1], { extrapolateRight: "clamp" });
              const itemSlide = spring({ fps, frame: frame - itemStart, config: { damping: 18 } });
              const slideY = interpolate(itemSlide, [0, 1], [30, 0]);
              const nodeScale = interpolate(itemSlide, [0, 1], [0.5, 1]);

              return (
                <div key={idx} style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "32px",
                  opacity: itemPanelFade,
                  transition: "none"
                }}>
                  {/* Glowing Node */}
                  <div style={{
                    width: "48px",
                    height: "48px",
                    borderRadius: "50%",
                    background: "rgba(255,255,255,0.02)",
                    border: `1px solid rgba(255,255,255,0.1)`,
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    boxShadow: `inset 0 0 10px rgba(255,255,255,0.05), 0 0 20px ${accentColor}20`,
                    zIndex: 2,
                    backdropFilter: "blur(10px)",
                    WebkitBackdropFilter: "blur(10px)",
                    transform: `scale(${nodeScale})`,
                    transition: "none"
                  }}>
                    <div style={{ 
                      width: "12px", 
                      height: "12px", 
                      borderRadius: "50%", 
                      background: accentColor, 
                      boxShadow: `0 0 12px ${accentColor}` 
                    }} />
                  </div>

                  {/* Text Container (Masked) */}
                  <div style={{
                    flex: 1,
                    background: "rgba(255,255,255,0.02)",
                    border: "1px solid rgba(255,255,255,0.08)",
                    borderRadius: "24px",
                    padding: "32px 40px",
                    boxShadow: "0 10px 30px rgba(0,0,0,0.2)",
                    overflow: "hidden"
                  }}>
                    <div style={{
                       transform: `translateY(${slideY}px)`,
                       opacity: itemFade,
                       transition: "none",
                       fontSize: "36px",
                       fontWeight: 400,
                       color: "rgba(255,255,255,0.9)",
                       letterSpacing: "0.02em",
                    }}>
                       {item}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default StructureTakeover;